<?php
namespace App\Jobs;
use App\Contracts\ProtectedMediaStorage;use App\Models\{MediaAsset,MediaVariant,StorageLedgerEntry,User};use App\Support\WatermarkPosition;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Queue\Middleware\WithoutOverlapping;use Illuminate\Support\Str;use RuntimeException;
class GenerateWatermarkedVariant implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=3;public function __construct(public int$assetId,public ?int$requestedVersion=null){$this->onQueue('media-default');}public function middleware():array{return[(new WithoutOverlapping('watermark-'.$this->assetId))->expireAfter(180)->dontRelease()];}public function handle(ProtectedMediaStorage$s):void{$a=MediaAsset::with('group.creator.watermarkSetting')->findOrFail($this->assetId);$g=$a->group;$w=$g?->creator?->watermarkSetting;$version=$this->requestedVersion??$w?->settings_version;if(!$g?->watermark_enabled||!$w?->hasLogo()||$version!==$w->settings_version)return;if($a->variants()->where('variant_type','watermarked')->where('version',$version)->where('state','ready')->exists())return;$source=$a->variant('optimized');if(!$source)throw new RuntimeException('Optimized source unavailable.');$image=$this->image($s,$source->object_key);$logo=$this->image($s,$w->logo_object_key);$iw=imagesx($image);$ih=imagesy($image);$lw=imagesx($logo);$lh=imagesy($logo);$ww=max(1,min($iw,(int)round($iw*$w->size_percentage/100)));$wh=max(1,(int)round($lh*($ww/$lw)));if($wh>$ih){$wh=$ih;$ww=max(1,(int)round($lw*($wh/$lh)));}$resized=imagecreatetruecolor($ww,$wh);imagealphablending($resized,false);imagesavealpha($resized,true);imagefill($resized,0,0,imagecolorallocatealpha($resized,0,0,0,127));imagecopyresampled($resized,$logo,0,0,0,0,$ww,$wh,$lw,$lh);[$x,$y]=WatermarkPosition::coordinates($w->position,$iw,$ih,$ww,$wh);imagealphablending($image,true);imagecopy($image,$resized,max(0,$x),max(0,$y),0,0,$ww,$wh);ob_start();$mime=$source->mime_type;if($mime==='image/png')imagepng($image,null,6);elseif($mime==='image/webp'&&function_exists('imagewebp'))imagewebp($image,null,88);else{$mime='image/jpeg';imagejpeg($image,null,88);}$bytes=(string)ob_get_clean();imagedestroy($resized);imagedestroy($logo);imagedestroy($image);$current=$g->creator->watermarkSetting()->first();if(!$current||$current->settings_version!==$version)return;$ext=['image/png'=>'png','image/webp'=>'webp'][$mime]??'jpg';$key=config('media.prefixes.watermarked').'/groups/'.$a->group_id.'/'.Str::uuid().'.'.$ext;$s->put($key,$bytes,$mime);$current=$g->creator->watermarkSetting()->first();if(!$current||$current->settings_version!==$version){$s->delete($key);return;}MediaVariant::updateOrCreate(['media_asset_id'=>$a->id,'variant_type'=>'watermarked','version'=>$version],['storage_disk'=>$s->disk(),'object_key'=>$key,'mime_type'=>$mime,'size_bytes'=>strlen($bytes),'checksum_sha256'=>hash('sha256',$bytes),'width'=>$iw,'height'=>$ih,'state'=>'ready','error'=>null]);$ledger=StorageLedgerEntry::firstOrCreate(['idempotency_key'=>'watermark-'.$a->uuid.'-'.$version],['owner_id'=>$a->owner_id,'group_id'=>$a->group_id,'media_asset_id'=>$a->id,'event_type'=>'variant_created','byte_delta'=>strlen($bytes)]);if($ledger->wasRecentlyCreated)User::whereKey($a->owner_id)->increment('storage_used',strlen($bytes));}private function image(ProtectedMediaStorage$s,string$key){$stream=$s->readStream($key);$bytes=stream_get_contents($stream);fclose($stream);$im=@imagecreatefromstring($bytes);if(!$im)throw new RuntimeException('Watermark image invalid.');return$im;}}
